import fs from "node:fs";

export interface AppConfig {
  apiEndpoint: string;
  retries: number;
}

export function loadConfig(path: string): AppConfig {
  const raw = fs.readFileSync(path, "utf8");
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(`Failed to parse config JSON: ${err}`);
  }

  if (typeof parsed.apiEndpoint !== 'string') {
    throw new Error(`Config must have a string field 'apiEndpoint'`);
  }
  if (typeof parsed.retries !== 'number') {
    throw new Error(`Config must have a number field 'retries'`);
  }

  return parsed as AppConfig;
}

